const $=s=>document.querySelector(s), esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'LKR '+n.toLocaleString('en-LK'), compact=n=>'LKR '+(n/1000000).toFixed(2)+'M';
let storageOK=true;function load(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{storageOK=false;return f}}function persist(){try{localStorage.setItem('vx-rules',JSON.stringify(rules));localStorage.setItem('vx-cases',JSON.stringify(cases))}catch{storageOK=false;toast('Storage unavailable. Changes last for this session.')}}
let rules=load('vx-rules',structuredClone(GL.defaults)),cases=load('vx-cases',{}),rows=GL.generate(),alerts=GL.evaluate(rows,rules),page='overview',query='',branch='All branches',severity='All severities',status='All statuses';
const recon=[{id:'REC-001',account:'Cash at bank',branch:'Colombo',gl:12450000,source:12425000,reason:'Bank fee not posted',age:3},{id:'REC-002',account:'Interbranch clearing',branch:'Galle',gl:1800000,source:1650000,reason:'Counterpart posting missing',age:7},{id:'REC-003',account:'Customer deposits',branch:'Kandy',gl:8600000,source:8680000,reason:'Settlement timing difference',age:1},{id:'REC-004',account:'Interest receivable',branch:'Kurunegala',gl:3250000,source:3250000,reason:'Matched',age:0}];
const state=id=>cases[id]||{status:'Open',owner:'Unassigned',notes:[]}, badge=(s)=>`<span class="pill ${s}">${s}</span>`;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function heading(title,sub,buttons=''){return `<div class="heading"><div><div class="eyebrow">GL RISK INTELLIGENCE</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${buttons}</div></div>`}
function filtered(data){return data.filter(t=>(branch==='All branches'||t.branch===branch)&&(severity==='All severities'||t.severity===severity)&&(status==='All statuses'||state(t.id).status===status)&&(!query||[t.id,t.account,t.reference,t.description,t.branch].join(' ').toLowerCase().includes(query.toLowerCase())))}
function filters(isAlerts=true){return `<div class="filters"><input type="search" id="search" aria-label="Search journals" placeholder="Search journal, account or reference…" value="${esc(query)}"><select id="branch" aria-label="Branch">${['All branches','Colombo','Kandy','Galle','Kurunegala'].map(x=>`<option ${x===branch?'selected':''}>${x}</option>`).join('')}</select>${isAlerts?`<select id="severity" aria-label="Severity">${['All severities','High','Medium'].map(x=>`<option ${x===severity?'selected':''}>${x}</option>`).join('')}</select><select id="status" aria-label="Case status">${['All statuses','Open','Investigating','Resolved'].map(x=>`<option ${x===status?'selected':''}>${x}</option>`).join('')}</select>`:''}<button id="clear">Clear filters</button></div>`}
function table(data,isAlerts=true){return `<div class="tablewrap"><table><thead><tr><th>Journal / account</th><th>Branch / date</th>${isAlerts?'<th>Detection signal</th><th>Severity</th>':'<th>Reference</th><th>Side</th>'}<th class="right">Amount</th>${isAlerts?'<th>Status</th>':''}<th></th></tr></thead><tbody>${data.map(t=>`<tr class="clickable" data-detail="${t.id}"><td><strong>${t.id}</strong><small>${esc(t.account)}</small></td><td>${t.branch}<small>${t.date} · ${String(t.hour).padStart(2,'0')}:00</small></td>${isAlerts?`<td>${t.hits[0].name}${t.hits.length>1?` <span class="pill">+${t.hits.length-1}</span>`:''}</td><td>${badge(t.severity)}</td>`:`<td>${t.reference}</td><td>${t.side}</td>`}<td class="right"><strong>${money(t.amount)}</strong></td>${isAlerts?`<td>${badge(state(t.id).status)}</td>`:''}<td><button class="link" data-detail="${t.id}" aria-label="Investigate ${t.id}">View ↗</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No journals match these filters.</td></tr>'}</tbody></table></div>`}
function render(){page=location.hash.slice(1)||'overview';if(!['overview','exceptions','transactions','rules','reconciliation'].includes(page))page='overview';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));let html='';
if(page==='overview'){const high=alerts.filter(x=>x.severity==='High').length,total=rows.reduce((s,t)=>s+t.amount,0),risk=alerts.reduce((s,t)=>s+t.amount,0);html=heading('A clearer view of ledger risk','Monitor unusual activity. Understand the signals. Act with confidence.','<span class="pill">01–30 Sep 2026</span><button id="run" class="primary">↻ Run detection</button>')+`<div class="stats"><div class="stat accent"><label>Journals analysed</label><strong>${rows.length}</strong><small>${compact(total)} total journal value</small></div><div class="stat"><label>Flagged journals</label><strong>${alerts.length} <span style="font-size:13px;color:#8796a5">/ ${rows.length}</span></strong><small>${(alerts.length/rows.length*100).toFixed(1)}% of synthetic journals</small></div><div class="stat warn"><label>High-severity exceptions</label><strong>${high}</strong><small>${alerts.filter(x=>state(x.id).status!=='Resolved').length} open or under investigation</small></div><div class="stat"><label>Flagged journal value</label><strong>${compact(risk)}</strong><small>Unique journals · not an estimated loss</small></div></div><div class="grid"><section class="panel"><div class="panelhead"><div><h2>Risk signals over time</h2><small>Flagged journals by posting date · September 2026</small></div><span class="pill">Daily</span></div><div class="chart">${Array.from({length:30},(_,i)=>{let n=alerts.filter(t=>+t.date.slice(-2)===i+1).length;return `<div class="barcol" title="Sep ${i+1}: ${n} flagged journals"><small>${n||''}</small><div class="bar ${n?'hot':''}" style="height:${n?Math.max(15,n*42):3}px"></div></div>`}).join('')}</div><div class="chartlabels"><span>01 Sep</span><span>10 Sep</span><span>20 Sep</span><span>30 Sep</span></div><div class="legend"><i></i> Rule-based detection · ${rules.filter(r=>r.enabled).length} active rules</div></section><section class="panel"><div class="panelhead"><div><h2>What’s driving exceptions</h2><small>Rule hits · journals can trigger multiple rules</small></div></div>${rules.map(r=>({r,n:alerts.filter(t=>t.hits.some(h=>h.id===r.id)).length})).sort((a,b)=>b.n-a.n).slice(0,5).map(({r,n})=>`<div class="rulebar"><span>${r.name}</span><div class="track"><i style="width:${n/Math.max(1,alerts.length)*100}%"></i></div><b>${n}</b></div>`).join('')}</section></div><section class="panel"><div class="panelhead"><div><h2>Priority investigation queue</h2><small>Highest risk scores first · click a journal to inspect evidence</small></div><a class="link" href="#exceptions">View all exceptions →</a></div>${table([...alerts].sort((a,b)=>b.score-a.score).slice(0,5))}</section>`;}
if(page==='exceptions'||page==='transactions'){let is=page==='exceptions',data=filtered(is?alerts:rows);html=heading(is?'Exception workbench':'General ledger',is?'Review rule evidence, assign an investigator and document decisions.':'Explore the synthetic posting population used by the detection engine.','<button id="export">↓ Export CSV</button>')+filters(is)+`<section class="panel"><div class="panelhead"><h2>${is?'Detected exceptions':'Synthetic journal register'}</h2><span class="count">${data.length} journals</span></div>${table(data,is)}</section>`;}
if(page==='rules'){html=heading('Detection rules','Transparent controls. Configurable thresholds. Explainable results.','<button id="resetRules">Restore defaults</button><button class="primary" id="saveRules">Save & run detection</button>')+`<div class="callout"><b>Designed for MBSL’s requirements.</b> These are illustrative rules. Production GL anomaly detection logic will be custom-developed based on MBSL’s requirements, accounting practices, transaction characteristics, and available data. vxFRMS provides the underlying implementation framework.</div><div class="rulegrid">${rules.map(r=>`<section class="panel rulecard"><label><span><span class="eyebrow">${r.id} · ${r.kind.toUpperCase()}</span><h3>${r.name}</h3></span><input aria-label="Enable ${r.name}" type="checkbox" data-enabled="${r.id}" ${r.enabled?'checked':''}></label><p>${r.description}</p><div class="ruleinputs"><label><small>${['amount','period','interbranch'].includes(r.kind)?'Threshold (LKR)':r.kind==='hours'?'Closing hour (08–24)':r.kind==='dormant'?'Inactive days':'Minimum count'}</small><input type="number" min="${r.kind==='hours'?9:r.kind==='duplicate'?2:1}" max="${r.kind==='hours'?24:999999999}" value="${r.threshold}" data-threshold="${r.id}" aria-label="${r.name} threshold"></label><label><small>Severity</small><select data-ruleSeverity="${r.id}" aria-label="${r.name} severity"><option ${r.severity==='High'?'selected':''}>High</option><option ${r.severity==='Medium'?'selected':''}>Medium</option></select></label></div></section>`).join('')}</div>`;}
if(page==='reconciliation'){let delta=recon.reduce((s,r)=>s+Math.abs(r.gl-r.source),0);html=heading('Reconciliation intelligence','Illustrative GL-to-source balances as at 30 September 2026.','<button id="exportRecon">↓ Export CSV</button>')+`<div class="stats"><div class="stat"><label>Accounts compared</label><strong>4</strong><small>Synthetic balance snapshots</small></div><div class="stat warn"><label>Unmatched accounts</label><strong>3</strong><small>Absolute variance greater than zero</small></div><div class="stat"><label>Total absolute variance</label><strong>${money(delta)}</strong><small>Not netted across accounts</small></div><div class="stat accent"><label>Matched accounts</label><strong>1</strong><small>Zero balance variance</small></div></div><section class="panel"><div class="panelhead"><div><h2>Balance comparison</h2><small>Click an exception for investigation and illustrative supporting evidence</small></div></div><div class="tablewrap"><table><thead><tr><th>Account / branch</th><th>GL balance</th><th>Source balance</th><th>GL − source</th><th>Exception / age</th><th>Status</th><th></th></tr></thead><tbody>${recon.map(r=>`<tr><td><strong>${r.account}</strong><small>${r.branch} · ${r.id}</small></td><td>${money(r.gl)}</td><td>${money(r.source)}</td><td>${money(r.gl-r.source)}</td><td>${r.reason}<small>${r.age} days outstanding</small></td><td>${badge(r.gl===r.source?'Matched':state(r.id).status)}</td><td><button class="link" data-recon="${r.id}">View ↗</button></td></tr>`).join('')}</tbody></table></div></section><div class="callout" style="margin-top:20px">Balances are standalone synthetic snapshots; they are not derived from the journal register. Matching uses exact balance equality for this prototype. Production matching, timing tolerances, ageing and source integrations require agreed business specifications.</div>`;}
$('#main').innerHTML=html;bind();}
function download(name,data){const csv=data.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportJournals(){let data=filtered(page==='exceptions'?alerts:rows);download('SYNTHETIC-GL-'+page+'.csv',[['Demo data','Journal','Date','Branch','Account','Reference','Side','LKR amount','Rules','Status'],...data.map(t=>['SYNTHETIC',t.id,t.date,t.branch,t.account,t.reference,t.side,t.amount,t.hits?.map(r=>r.name).join('; ')||'',state(t.id).status])]);}
function bind(){document.querySelectorAll('[data-detail]').forEach(el=>el.onclick=e=>{e.stopPropagation();detail(el.dataset.detail)});document.querySelectorAll('[data-recon]').forEach(el=>el.onclick=()=>detail(el.dataset.recon,true));for(const id of ['branch','severity','status'])if($('#'+id))$('#'+id).onchange=e=>{if(id==='branch')branch=e.target.value;if(id==='severity')severity=e.target.value;if(id==='status')status=e.target.value;render()};if($('#search'))$('#search').oninput=e=>{let pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#clear'))$('#clear').onclick=()=>{query='';branch='All branches';severity='All severities';status='All statuses';render()};if($('#export'))$('#export').onclick=exportJournals;if($('#run'))$('#run').onclick=()=>{alerts=GL.evaluate(rows,rules);render();toast('Detection complete · '+alerts.length+' journals flagged')};if($('#saveRules'))$('#saveRules').onclick=()=>{let next=structuredClone(rules);for(let r of next){let input=$(`[data-threshold="${r.id}"]`);if(!input.checkValidity()||!Number.isFinite(+input.value)||!input.value){input.reportValidity();return}r.threshold=+input.value;r.enabled=$(`[data-enabled="${r.id}"]`).checked;r.severity=$(`[data-ruleSeverity="${r.id}"]`).value;}rules=next;persist();alerts=GL.evaluate(rows,rules);render();toast('Rules saved · '+alerts.length+' journals flagged')};if($('#resetRules'))$('#resetRules').onclick=()=>{rules=structuredClone(GL.defaults);persist();alerts=GL.evaluate(rows,rules);render();toast('Default rules restored')};if($('#exportRecon'))$('#exportRecon').onclick=()=>download('SYNTHETIC-reconciliation.csv',[['Demo data','ID','Account','Branch','GL','Source','Variance','Reason','Status'],...recon.map(r=>['SYNTHETIC',r.id,r.account,r.branch,r.gl,r.source,r.gl-r.source,r.reason,r.gl===r.source?'Matched':state(r.id).status])]);}
function detail(id,isRecon=false){let t=isRecon?recon.find(x=>x.id===id):(alerts.find(x=>x.id===id)||rows.find(x=>x.id===id)),s=state(id);let facts=isRecon?[['GL balance',money(t.gl)],['Source balance',money(t.source)],['Variance (GL − source)',money(t.gl-t.source)],['Age',t.age+' days']]:[['Amount',money(t.amount)],['Posting',t.date+' '+String(t.hour).padStart(2,'0')+':00 (Sri Lanka)'],['Reference',t.reference],['Posting operator',t.operator],['Side',t.side],['Risk score',t.score?t.score+'/99 · illustrative':'No active rule hit']];$('#detailContent').innerHTML=`<div class="panelhead"><div><div class="eyebrow">SYNTHETIC ${isRecon?'RECONCILIATION':'JOURNAL'}</div><h1>${id}</h1><small>${esc(t.account)} · ${t.branch}</small></div><button id="closeDetail" aria-label="Close investigation">✕</button></div><div class="detailgrid">${facts.map(([k,v])=>`<div><label>${k}</label><strong>${esc(v)}</strong></div>`).join('')}</div><h3>${isRecon?'Reconciliation evidence':'Detection evidence'}</h3>${isRecon?`<div class="evidence">${t.reason}. GL ${money(t.gl)} compared with synthetic source ${money(t.source)}. ${t.gl===t.source?'No variance.':'Suggested review: inspect source statement and missing or timing-related postings.'}</div>`:(t.hits||[]).map(r=>`<div class="evidence"><b>${r.id} · ${r.name}</b><br>${esc(r.description)}<br>Configured threshold: ${r.threshold.toLocaleString()} · Observed: ${esc(observed(r,t))}</div>`).join('')||'<div class="callout">No enabled detection rule currently flags this journal.</div>'}<h3>Investigation · browser-local demo</h3><div class="filters"><select id="caseStatus" aria-label="Investigation status">${['Open','Investigating','Resolved'].map(x=>`<option ${x===s.status?'selected':''}>${x}</option>`).join('')}</select><select id="caseOwner" aria-label="Investigator">${['Unassigned','Demo Analyst A','Demo Analyst B'].map(x=>`<option ${x===s.owner?'selected':''}>${x}</option>`).join('')}</select></div><textarea id="caseNote" aria-label="Investigation note" placeholder="Add a finding or resolution rationale (synthetic information only)…" maxlength="2000"></textarea><button id="saveCase" class="primary">Save investigation</button><h3>Investigation history</h3>${s.notes.map(n=>`<div class="audit"><small>${esc(n.at)} · ${esc(n.owner)} · ${esc(n.status)}</small><br>${esc(n.text)}</div>`).join('')||'<small>No investigation activity recorded yet.</small>'}<p><small>Local demonstration history is editable and is not a production audit trail.</small></p>`;$('#closeDetail').onclick=()=>$('#detail').close();$('#saveCase').onclick=()=>{let note=$('#caseNote').value.trim(),newStatus=$('#caseStatus').value;if(newStatus==='Resolved'&&!note){toast('Add a resolution rationale before resolving.');$('#caseNote').focus();return}cases[id]={status:newStatus,owner:$('#caseOwner').value,notes:[{at:new Date().toLocaleString('en-GB',{timeZone:'Asia/Colombo'})+' SLST',owner:$('#caseOwner').value,status:newStatus,text:note||'Investigation status or assignment updated.'},...s.notes]};persist();render();detail(id,isRecon);toast('Investigation saved in this browser')};if(!$('#detail').open)$('#detail').showModal();}
function observed(r,t){switch(r.kind){case'amount':case'period':return money(t.amount);case'hours':return String(t.hour).padStart(2,'0')+':00';case'dormant':return t.inactiveDays+' inactive days';case'reversal':return t.reversals+' reversals';case'duplicate':return rows.filter(x=>x.reference===t.reference&&x.account===t.account&&x.branch===t.branch&&x.date===t.date&&x.amount===t.amount).length+' matching journals';case'interbranch':return money(Math.abs(t.amount-t.counterpart))+' absolute difference';}}
window.addEventListener('hashchange',()=>{query='';branch='All branches';severity='All severities';status='All statuses';render();window.scrollTo(0,0)});render();
